import subprocess,json,shutil,os,itertools
def det_one(ext, contents):
    d='/tmp/probe/w'
    shutil.rmtree(d,ignore_errors=True); os.makedirs(d)
    files=[]
    for i,c in enumerate(contents):
        fn='a%03d.%s'%(i,ext)
        open(d+'/'+fn,'w').write(c)
        files.append(fn)
    r=json.loads(subprocess.run(['/workspace/executable','--by-file','--format','json','.'],cwd=d,capture_output=True,text=True).stdout)
    m={}
    for l in r:
        for f in l['Files']:
            m[f['Filename']]=l['Name']
    return [m.get(files[i],'MISSING') for i in range(len(contents))]

def minimal_triggers(ext, target, seeds, minlen=2, maxlen=None):
    """find minimal substrings of seeds that resolve ext->target"""
    cands=set()
    for s in seeds:
        n=len(s)
        hi = n if maxlen is None else min(n,maxlen)
        for L in range(minlen, hi+1):
            for i in range(0, n-L+1):
                cands.add(s[i:i+L])
    cands=sorted(cands, key=lambda x: (len(x),x))
    res=det_one(ext, cands)
    trig=[]
    for c,t in zip(cands,res):
        if t==target: trig.append(c)
    # minimal
    out=[]
    for c in trig:
        if not any(c in o for o in out):
            out.append(c)
    return out
