D='/tmp/probe/w'
def fresh():
    shutil.rmtree(D,ignore_errors=True)
    for _ in range(3):
        if not os.path.exists(D): break
        for f in glob.glob(D+'/*'):
            try: os.remove(f)
            except: shutil.rmtree(f,ignore_errors=True)
        shutil.rmtree(D,ignore_errors=True)
    os.makedirs(D,exist_ok=True)
def det_one(ext, contents):
    fresh()
    files=[]
    for i,c in enumerate(contents):
        fn='a%03d.%s'%(i,ext)
        open(D+'/'+fn,'w').write(c)
        files.append(fn)
    r=json.loads(subprocess.run(['/workspace/executable','--by-file','--format','json','.'],cwd=D,capture_output=True,text=True).stdout)
    m={}
    for l in r:
        for f in l['Files']:
            m[f['Filename']]=l['Name']
    return [m.get(files[i],'MISSING') for i in range(len(contents))]
def minimal_triggers(ext, target, seeds, minlen=2, maxlen=None):
    cands=set()
    for s in seeds:
        n=len(s)
        hi = n if maxlen is None else min(n,maxlen)
        for L in range(minlen, hi+1):
            for i in range(0, n-L+1):
                cands.add(s[i:i+L])
    cands=sorted(cands, key=lambda x: (len(x),x))
    res=det_one(ext, cands)
    trig=[c for c,t in zip(cands,res) if t==target]
    out=[]
    for c in trig:
        if not any(o in c for o in out):
            out.append(c)
    return out
