{"command": "cat > /tmp/probe/h.py <<'PYEOF'
import subprocess,json,shutil,os,sys,glob
D='/tmp/probe/w'
def fresh():
    shutil.rmtree(D,ignore_errors=True)
    if os.path.exists(D):
        for f in glob.glob(D+'/*'):
            try: os.remove(f)
            except: shutil.rmtree(f,ignore_errors=True)
        shutil.rmtree(D,ignore_errors=True)
    os.makedirs(D,exist_ok=True)
def run(content, ext='go', flags=None):
    fresh()
    open(D+'/a.'+ext,'w').write(content)
    args=['/workspace/executable']+ (flags or []) +['--format','json','.']
    out=subprocess.run(args,cwd=D,capture_output=True,text=True)
    try:
        r=json.loads(out.stdout)
    except Exception:
        return {'ERR':out.stdout[:200]+out.stderr[:200]}
    return [(x['Name'],x['Lines'],x['Code'],x['Comment'],x['Blank'],x['Complexity']) for x in r]
def show(content, ext='go', flags=None):
    print('%-30s'%repr(content), run(content,ext,flags))
