LANGINFO=json.load(open('/tmp/probe/langinfo.json'))

PREFIX = {
 'Coq':'zz\n','V':'pub\n','Verilog':'','Objective C':'@interface\n','MATLAB':'zz\n','JSON':'zz\n',
 'YAML':'zz\n','CloudFormation (YAML)':'Resources:\nType: AWS::\n','LaTeX':'zz\n','HEEx':'zz\n',
 'CloudFormation (JSON)':'zz\n',
}
PROBEEXT = {'Verilog':'vg','Treetop':'treetop','TemplateToolkit':'tt2','TeX':'sty','Phoenix LiveView':'leex'}

def probe(lang):
    info=LANGINFO[lang]
    ext=PROBEEXT.get(lang, info['probe'])
    prefix=PREFIX.get(lang,'')
    pl=prefix.count('\n')
    res={'lang':lang,'ext':ext,'prefix':prefix}
    # PROBE1 comments
    files={}
    idx={}
    for i,c in enumerate(LINE_CANDS):
        n='c%04d.%s'%(i,ext)
        files[n]=prefix+'zz\n'+c+'\nzz\n'
        idx[n]=c
    m=run_batch(files)
    lines={}; blocks={}
    unknown=[]
    for n,v in m.items():
        c=idx[n]
        name,L,C,K,B,X=v
        if name!=lang:  # language mismatch -> skip
            res['mismatch']=True
            continue
        if K==1 and C==pl+2: lines[c]=True
        elif K==2 and C==pl+1: blocks[c]=True
        elif K==0 and C==pl+3: unknown.append(c)
        else: res.setdefault('odd',[]).append((c,L,C,K,B,X))
    res['line']=sorted(lines)
    res['blockstart']=sorted(blocks)
    res['unknown']=sorted(unknown)
    return res

if __name__=='__main__':
    langs=sys.argv[1:] or list(LANGINFO)
    out={}
    t0=time.time()
    for lang in langs:
        out[lang]=probe(lang)
