{"command": "cd /tmp && python3 - <<'EOF'
import re,collections,json,subprocess,shutil,os,sys
exts=set()
langof={}
for l in open('/tmp/langs.txt'):
    m=re.match(r'^(.*) \((.*)\)$', l.strip())
    name=m.group(1)
    for e in m.group(2).split(','):
        if '.' not in e:
            exts.add(e); langof.setdefault(e,set()).add(name)
exts=sorted(exts)
print('exts without dot:',len(exts))
D='/tmp/probe/em8'
shutil.rmtree(D,ignore_errors=True); os.makedirs(D)
for i,e in enumerate(exts):
    open('%s/f%04d'%(D,i),'w').write('x\n')
open('/tmp/probe/em8names.txt','w').write('\n'.join('%04d|%s'%(i,e) for i,e in enumerate(exts)))
r=json.loads(subprocess.run(['/workspace/executable','--by-file','--format','json','.'],cwd=D,capture_output=True,text=True).stdout)
m={}
for l in r:
    for f in l['Files']: m[f['Filename']]=(l['Name'],f['Extension'])
hits=[]
for i,e in enumerate(exts):
    n='f%04d'%i
    if n in m: hits.append((e,langof[e],m[n][0],m[n][1]))
print('matched',len(hits))
for h in hits[:80]: print(h)
EOF"}

