for i,e in enumerate(exts):
    fn=e
    open(D+'/'+fn,'w').write('x\n'); names.append(fn)
r=json.loads(subprocess.run(['/workspace/executable','--by-file','--format','json','.'],cwd=D,capture_output=True,text=True).stdout)
m={}
for l in r:
    for f in l['Files']: m[f['Filename']]=(l['Name'],f['Extension'])
hits=[]
for e in exts:
    if e in m: hits.append((e,sorted(langof[e]),m[e][0],m[e][1]))
print('total exts',len(exts),'matched',len(hits))
for h in hits: print(h)
EOF"}

