{"command": "cat > /workspace/src/parse.go <<'EOF'
package main

import (
	"strings"
)

// FileStat holds the per file statistics collected while parsing.
type FileStat struct {
	Language          string
	PossibleLanguages []string
	Filename          string
	Extension         string
	Location          string
	Symlocation       string
	Bytes             int64
	Lines             int
	Code              int
	Comment           int
	Blank             int
	Complexity        int
	WeightedComplexity float64
	Hash              string
	Binary            bool
	Minified          bool
	Generated         bool
	EndPoint          int
	Uloc              int
	MaxLine           int
	MeanLine          float64
	HasLineLength     bool
}

func isSpaceByte(c byte) bool {
	return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\v' || c == '\f'
}

// splitLines mirrors the way the reference tool splits a file into lines.
func splitLines(content string) []string {
	if content == "" {
		return nil
	}
	lines := strings.Split(content, "\n")
	if len(lines) > 0 && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
	}
	return lines
}

// matchToken returns the length of the longest token in list that prefixes s at position 0
func matchToken(s string, list []string) (int, int) {
	best := -1
	bestLen := 0
	for i, t := range list {
		if len(t) == 0 {
			continue
		}
		if len(s) >= len(t) && s[:len(t)] == t {
			if len(t) > bestLen {
				bestLen = len(t)
				best = i
			}
		}
	}
	return best, bestLen
}

// countComplexity counts complexity checks inside the code sections of a single line.
func countComplexity(line string, lang *LangDef, pos int, inBlock bool, blockEnd string, strIdx int) int {
	if len(lang.Checks) == 0 {
		return 0
	}
	total := 0
	i := 0
	n := len(line)
	for i < n {
		if inBlock {
			idx := strings.Index(line[i:], blockEnd)
			if idx < 0 {
				i = n
			} else {
				i += idx + len(blockEnd)
				inBlock = false
			}
			continue
		}
		if strIdx >= 0 {
			end := lang.Strs[strIdx][1]
			j := i
			for j < n {
				k := strings.Index(line[j:], end)
				if k < 0 {
					j = n
					break
				}
				// handle escape
				esc := false
				if k > 0 && line[j+k-1] == '\\' {
					cnt := 0
					p := j + k - 1
					for p >= j && line[p] == '\\' {
						cnt++
						p--
					}
					if cnt%2 == 1 {
						esc = true
					}
				}
				if !esc {
					j = j + k + len(end)
					strIdx = -1
					break
				}
				j = j + k + len(end)
			}
			i = j
			continue
		}
		c := line[i]
		if isSpaceByte(c) {
			i++
			continue
		}
		// check comments / strings
		if bi, bl := matchToken(line[i:], lang.Line); bi >= 0 {
			i = n
			continue
		}
		matched := false
		for pi, p := range lang.Block {
			if len(line)-i >= len(p[0]) && line[i:i+len(p[0])] == p[0] {
				inBlock = true
				blockEnd = p[1]
				i += len(p[0])
				matched = true
				break
			}
		}
		if matched {
			continue
		}
		for si, st := range lang.Strs {
			if len(line)-i >= len(st[0]) && line[i:i+len(st[0])] == st[0] {
				strIdx = si
				i += len(st[0])
				matched = true
				break
			}
		}
		if matched {
			continue
		}
		// code character: check for complexity checks starting here
		for _, ck := range lang.Checks {
			if len(ck) <= n-i && line[i:i+len(ck)] == ck {
				if i == 0 || isSpaceByte(line[i-1]) {
					total++
				}
			}
		}
		i++
	}
	return total
}

// Parse computes all statistics for a file.
func Parse(content string, lang *LangDef) (fs FileStat) {
	fs.Bytes = int64(len(content))
	lines := splitLines(content)
	fs.Lines = len(lines)
	inBlock := false
	blockEnd := ""
	strIdx := -1
	for _, line := range lines {
		hasCode := false
		nonSpace := false
		i := 0
		n := len(line)
		for i < n {
			if inBlock {
				idx := strings.Index(line[i:], blockEnd)
				if idx < 0 {
					i = n
				} else {
					i += idx + len(blockEnd)
					inBlock = false
				}
				continue
			}
			if strIdx >= 0 {
				end := lang.Strs[strIdx][1]
				j := i
				done := false
				for j < n {
					k := strings.Index(line[j:], end)
					if k < 0 {
						j = n
						break
					}
					esc := false
					if k > 0 && line[j+k-1] == '\\' {
						cnt := 0
						p := j + k - 1
						for p >= j && line[p] == '\\' {
							cnt++
							p--
						}
						if cnt%2 == 1 {
							esc = true
						}
					}
					if !esc {
						j = j + k + len(end)
						strIdx = -1
						done = true
						break
					}
					j = j + k + len(end)
				}
				i = j
				if done {
					// the string closing token itself counts as code
					hasCode = true
				}
				continue
			}
			c := line[i]
			if isSpaceByte(c) {
				i++
				continue
			}
			nonSpace = true
			if bi, bl := matchToken(line[i:], lang.Line); bi >= 0 && bl > 0 {
				i = n
				continue
			}
			matched := false
			for pi, p := range lang.Block {
				if len(line)-i >= len(p[0]) && line[i:i+len(p[0])] == p[0] {
					inBlock = true
					blockEnd = p[1]
					i += len(p[0])
					matched = true
					break
				}
			}
			if matched {
				continue
			}
			for si, st := range lang.Strs {
				if len(line)-i >= len(st[0]) && line[i:i+len(st[0])] == st[0] {
					strIdx = si
					i += len(st[0])
					matched = true
					break
				}
			}
			if matched {
				hasCode = true
				continue
			}
			hasCode = true
			i++
		}
		if hasCode {
			fs.Code++
			fs.Complexity += countComplexity(line, lang, 0, inBlock, blockEnd, strIdx)
		} else if nonSpace {
			fs.Comment++
		} else {
			fs.Blank++
		}
		if len(line) > fs.MaxLine {
			fs.MaxLine = len(line)
		}
		fs.MeanLine += float64(len(line))
