// IgnoreRule holds a parsed gitignore style rule.
type IgnoreRule struct {
	Pattern   string
	Negate    bool
	DirOnly   bool
	Anchored  bool
	BaseDir   string
}

func parseIgnoreFile(path string, base string) []IgnoreRule {
	var rules []IgnoreRule
	f, err := os.Open(path)
	if err != nil {
		return rules
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		line := sc.Text()
		line = strings.TrimRight(line, "\r")
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		negate := false
		if strings.HasPrefix(line, "!") {
			negate = true
			line = line[1:]
		}
		if strings.HasSuffix(line, "\\ ") {
			line = line[:len(line)-2] + " "
		} else {
			line = strings.TrimRight(line, " ")
		}
		if line == "" {
			continue
		}
		dirOnly := false
		if strings.HasSuffix(line, "/") {
			dirOnly = true
			line = line[:len(line)-1]
		}
		anchored := strings.Contains(line, "/")
		line = strings.TrimPrefix(line, "/")
		if line == "" {
			continue
		}
		rules = append(rules, IgnoreRule{Pattern: line, Negate: negate, DirOnly: dirOnly, Anchored: anchored, BaseDir: base})
	}
	return rules
}

func matchIgnore(rules []IgnoreRule, rel string, isDir bool) bool {
	matched := false
	for _, r := range rules {
		if r.DirOnly && !isDir {
			continue
		}
		var pat string
		if r.Anchored {
			pat = r.Pattern
		} else {
			pat = "*/*" + r.Pattern
			pat = "**/" + r.Pattern
		}
		ok, _ := filepath.Match(pat, rel)
		if !ok && !r.Anchored {
			ok, _ = filepath.Match(r.Pattern, filepath.Base(rel))
		}
		if ok {
			matched = !r.Negate
		}
	}
	return matched
}

// Collector walks the file tree and collects statistics.
type Collector struct {
	Opts   *Options
	Files  []*FileStat
	mutex  sync.Mutex
	notMatch []*regexp.Regexp
	ignoreRules []IgnoreRule
}

func (c *Collector) excluded(path string) bool {
	for _, re := range c.notMatch {
		if re.MatchString(path) {
			return true
		}
	}
	return false
}

func (c *Collector) walk(root string) {
	info, err := os.Lstat(root)
	if err != nil {
		fmt.Printf("file or directory could not be read: %s\n", root)
		return
	}
	if !info.IsDir() {
		if info.Mode()&os.ModeSymlink != 0 {
			if !c.Opts.IncludeSymlinks {
				return
			}
			target, err := filepath.EvalSymlinks(root)
			if err == nil {
				c.processFile(root, target, info.Size())
			} else {
				c.processFile(root, root, info.Size())
			}
			return
		}
		c.processFile(root, root, info.Size())
		return
	}
	c.walkDir(root, "")
}

func (c *Collector) walkDir(dir string, rel string) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return
	}
	var subdirs []os.DirEntry
	for _, e := range entries {
		name := e.Name()
		full := filepath.Join(dir, name)
		relPath := name
		if rel != "" {
			relPath = rel + "/" + name
		}
		if c.excluded(relPath) || c.excluded(name) {
			continue
		}
		isDir := false
		isLink := false
		if e.Type()&os.ModeSymlink != 0 {
			isLink = true
		}
		if e.IsDir() {
			isDir = true
		}
		if isDir {
			if containsStr(c.Opts.ExcludeDir, name) {
				continue
			}
			if matchIgnore(c.ignoreRules, relPath, true) {
				continue
			}
			subdirs = append(subdirs, e)
			continue
		}
		if isLink {
			if !c.Opts.IncludeSymlinks {
				continue
			}
		}
		if containsStr(c.Opts.ExcludeFile, name) {
			continue
		}
		ext := extensionOf(name)
		if containsStr(c.Opts.ExcludeExt, ext) {
			continue
		}
		if len(c.Opts.IncludeExt) > 0 && !containsStr(c.Opts.IncludeExt, ext) {
			continue
		}
		if matchIgnore(c.ignoreRules, relPath, false) {
			continue
		}
		// language resolution
		key, list := ResolveLanguage(name)
		if list == nil {
			continue
		}
		info, err := e.Info()
		if err != nil {
			continue
		}
		if isLink {
			target, err := filepath.EvalSymlinks(full)
			if err == nil {
				c.processFileNamed(relPath, target, info.Size())
			} else {
				c.processFileNamed(relPath, full, info.Size())
			}
			continue
		}
		_ = key
		c.processFileNamed(relPath, full, info.Size())
	}
	for _, e := range subdirs {
		name := e.Name()
		relPath := name
		if rel != "" {
			relPath = rel + "/" + name
		}
		c.walkDir(filepath.Join(dir, name), relPath)
	}
}

func extensionOf(name string) string {
	i := strings.LastIndexByte(name, '.')
	if i < 0 {
		return ""
	}
	return name[i+1:]
}

func containsStr(list []string, s string) bool {
	for _, x := range list {
		if x == s {
			return true
		}
	}
	return false
}

func (c *Collector) processFileNamed(loc string, path string, size int64) {
	data, err := os.ReadFile(path)
	if err != nil {
		return
	}
	c.handleData(loc, "", filepath.Base(path), data)
}

func (c *Collector) processFile(loc string, path string, size int64) {
	data, err := os.ReadFile(path)
	if err != nil {
		return
	}
	c.handleData(loc, "", filepath.Base(path), data)
}

func (c *Collector) handleData(loc, symloc, filename string, data []byte) {
	name, list := ResolveLanguage(filename)
	if list == nil {
		return
	}
	lang := ChooseLanguage(list, string(data))
	fs := FileStat{
		Language:          lang.Name,
		PossibleLanguages: namesOf(list),
		Filename:          filename,
		Extension:         name,
		Location:          loc,
		Symlocation:       symloc,
		Bytes:             int64(len(data)),
	}
	if !c.Opts.Binary && isBinary(data) {
		return
	}
	st := Parse(string(data), lang)
	fs.Lines = st.Lines
	fs.Code = st.Code
	fs.Comment = st.Comment
	fs.Blank = st.Blank
	fs.Complexity = st.Complexity
	fs.Uloc = st.Uloc
	fs.MaxLine = st.MaxLine
	fs.MeanLine = st.MeanLine
	fs.HasLineLength = st.HasLineLength
	// minified / generated
	if c.Opts.MinGen || c.Opts.Min {
		if st.Lines > 0 && int64(st.Lines) > 0 && fs.Bytes/int64(st.Lines) >= int64(c.Opts.MinGenLineLength) {
			fs.Minified = true
		}
	}
	if c.Opts.Gen || c.Opts.MinGen {
		head := data
		if len(head) > 1024 {
			head = head[:1024]
		}
		low := strings.ToLower(string(head))
		for _, m := range c.Opts.GeneratedMarkers {
			if m != "" && strings.Contains(low, strings.ToLower(m)) {
				fs.Generated = true
				break
			}
		}
	}
	if !c.Opts.NoLarge {
		if fs.Bytes > int64(c.Opts.LargeByteCount) || fs.Lines > c.Opts.LargeLineCount {
			return
		}
	}
	if c.Opts.NoMinGen && (fs.Minified || fs.Generated) {
		return
	}
	if c.Opts.NoMin && fs.Minified {
		return
	}
	if c.Opts.NoGen && fs.Generated {
		return
	}
	c.mutex.Lock()
	c.Files = append(c.Files, &fs)
	c.mutex.Unlock()
}

func namesOf(list []*LangDef) []string {
	var out []string
	for _, l := range list {
		out = append(out, l.Name)
	}
	return out
}

func isBinary(data []byte) bool {
	n := len(data)
	if n > 10000 {
		n = 10000
	}
	for i := 0; i < n; i++ {
		if data[i] == 0 {
			return true
		}
	}
	return false
}

// Aggregate turns the collected file statistics into language rows.
func Aggregate(files []*FileStat, opts *Options) ([]*LangRow, *LangRow) {
	m := map[string]*LangRow{}
	var order []string
	total := &LangRow{Name: "Total"}
	for _, f := range files {
		row, ok := m[f.Language]
		if !ok {
			row = &LangRow{Name: f.Language}
			m[f.Language] = row
			order = append(order, f.Language)
		}
		row.Bytes += f.Bytes
		row.Lines += f.Lines
		row.Code += f.Code
		row.Comment += f.Comment
		row.Blank += f.Blank
		row.Complexity += f.Complexity
		row.Count++
		row.ULOC += f.Uloc
		row.Files = append(row.Files, f)
		if f.Complexity > 0 && f.Lines > 0 {
			row.WeightedComplexity += (float64(f.Complexity) / float64(f.Lines)) * float64(f.Code)
		}
		if f.HasLineLength {
			if row.LineLength == nil {
				row.LineLength = &LineLength{}
			}
			row.LineLength.Files++
			row.LineLength.Lines += f.Lines
			if f.MaxLine > row.LineLength.Max {
				row.LineLength.Max = f.MaxLine
			}
			row.LineLength.Average += f.MeanLine
		}
		total.Bytes += f.Bytes
		total.Lines += f.Lines
		total.Code += f.Code
		total.Comment += f.Comment
		total.Blank += f.Blank
		total.Complexity += f.Complexity
		total.Count++
		total.ULOC += f.Uloc
		if f.Complexity > 0 && f.Lines > 0 {
			total.WeightedComplexity += (float64(f.Complexity) / float64(f.Lines)) * float64(f.Code)
		}
	}
	var rows []*LangRow
	for _, name := range order {
		row := m[name]
		if row.LineLength != nil && row.LineLength.Files > 0 {
			row.LineLength.Average = row.LineLength.Average / float64(row.LineLength.Files)
		}
		rows = append(rows, row)
	}
	SortRows(rows, opts.Sort)
	return rows, total
}

// SortRows sorts language rows according to the selected column.
func SortRows(rows []*LangRow, sortKey string) {
	less := func(a, b *LangRow) bool {
		switch sortKey {
		case "name":
			return a.Name < b.Name
		case "lines":
			return a.Lines > b.Lines
		case "blanks":
			return a.Blank > b.Blank
		case "code":
			return a.Code > b.Code
		case "comments":
			return a.Comment > b.Comment
		case "complexity":
			return a.Complexity > b.Complexity
		default:
			if a.Count != b.Count {
				return a.Count > b.Count
			}
			return a.Name < b.Name
		}
	}
	sort.SliceStable(rows, func(i, j int) bool { return less(rows[i], rows[j]) })
}

// SortFiles sorts file statistics for by-file output.
func SortFiles(files []*FileStat, sortKey string) {
	less := func(a, b *FileStat) bool {
		switch sortKey {
		case "name":
			return a.Filename < b.Filename
		case "lines":
			return a.Lines > b.Lines
		case "blanks":
			return a.Blank > b.Blank
		case "code":
			return a.Code > b.Code
		case "comments":
			return a.Comment > b.Comment
		case "complexity":
			return a.Complexity > b.Complexity
		default:
			return a.Filename < b.Filename
		}
	}
	sort.SliceStable(files, func(i, j int) bool { return less(files[i], files[j]) })
}
