{"command": "cd /workspace && cat > src/format.go <<'GOEOF'
package main

import (
	"fmt"
	"sort"
	"strconv"
	"strings"
)

func comma(n int) string {
	s := strconv.Itoa(n)
	if len(s) <= 3 {
		return s
	}
	var out []string
	for len(s) > 3 {
		out = append([]string{s[len(s)-3:]}, out...)
		s = s[:len(s)-3]
	}
	out = append([]string{s}, out...)
	return strings.Join(out, ",")
}

func comma64(n int64) string { return comma(int(n)) }

func f1(v float64) string  { return trimFloat(v, 1) }
func f2(v float64) string  { return trimFloat(v, 2) }
func f3(v float64) string  { return trimFloat(v, 3) }

func trimFloat(v float64, prec int) string {
	s := strconv.FormatFloat(v, 'f', prec, 64)
	return s
}

var borderUnicode = strings.Repeat("â", 79)
var borderASCII = strings.Repeat("-", 79)

func border(ci bool) string {
	if ci {
		return borderASCII
	}
	return borderUnicode
}

func pct(v, total int) string {
	if total == 0 {
		return "NaN%"
	}
	return fmt.Sprintf("%.1f%%", float64(v)/float64(total)*100)
}

// SummaryRow is used by several formatters.
type SummaryRow struct {
	Name        string
	Files       int
	Lines       int
	Blank       int
	Comment     int
	Code        int
	Complexity  int
	Bytes       int64
	Uloc        int
	Weighted    float64
	LineLength  *LineLength
	Files_      []*FileStat
	Possible    []string
}

func toSummary(r *LangRow) SummaryRow {
	return SummaryRow{Name: r.Name, Files: r.Count, Lines: r.Lines, Blank: r.Blank, Comment: r.Comment,
		Code: r.Code, Complexity: r.Complexity, Bytes: r.Bytes, Uloc: r.ULOC, Weighted: r.WeightedComplexity,
		LineLength: r.LineLength, Files_: r.Files}
}

// Tabular produces the default human readable output.
func Tabular(rows []*LangRow, total *LangRow, files []*FileStat, o *Options) string {
	var b strings.Builder
	bd := border(o.Ci)
	b.WriteString(bd + "\n")
	if o.Wide {
		b.WriteString(fmt.Sprintf("%-38s%5s%10s%9s%10s%9s%11s%17s\n", "Language", "Files", "Lines", "Blanks", "Comments", "Code", "Complexity", "Complexity/Lines"))
	} else {
		b.WriteString(fmt.Sprintf("%-20s%5s%12s%10s%10s%11s%11s\n", "Language", "Files", "Lines", "Blanks", "Comments", "Code", "Complexity"))
	}
	b.WriteString(bd + "\n")
	for _, r := range rows {
		writeLangRow(&b, r, o)
	}
	if o.ByFile {
		for _, r := range rows {
			b.WriteString(bd + "\n")
			fr := append([]*FileStat{}, r.Files...)
			SortFiles(fr, o.Sort)
			for _, f := range fr {
				if o.Wide {
					cl := 0.0
					if f.Lines > 0 {
						cl = float64(f.Complexity) / float64(f.Lines)
					}
					b.WriteString(fmt.Sprintf("%-38s%5s%10s%9s%10s%9s%11s%17s\n", f.Location, "", comma(f.Lines), comma(f.Blank), comma(f.Comment), comma(f.Code), comma(f.Complexity), f2(cl)))
				} else {
					b.WriteString(fmt.Sprintf("%-20s%5s%12s%10s%10s%11s%11s\n", f.Location, "", comma(f.Lines), comma(f.Blank), comma(f.Comment), comma(f.Code), comma(f.Complexity)))
				}
			}
		}
	}
	b.WriteString(bd + "\n")
	if o.Wide {
		cl := 0.0
		if total.Lines > 0 {
			cl = float64(total.Complexity) / float64(total.Lines)
		}
		b.WriteString(fmt.Sprintf("%-38s%5s%10s%9s%10s%9s%11s%17s\n", "Total", comma(total.Count), comma(total.Lines), comma(total.Blank), comma(total.Comment), comma(total.Code), comma(total.Complexity), f2(cl)))
	} else {
		b.WriteString(fmt.Sprintf("%-20s%5s%12s%10s%10s%11s%11s\n", "Total", comma(total.Count), comma(total.Lines), comma(total.Blank), comma(total.Comment), comma(total.Code), comma(total.Complexity)))
	}
	b.WriteString(bd + "\n")
	if o.Uloc || o.Dryness {
		b.WriteString(subRow("Unique Lines of Code (ULOC)", comma(total.ULOC)))
		if o.Dryness {
			d := 0.0
			if total.Lines > 0 {
				d = float64(total.ULOC) / float64(total.Lines)
			}
			b.WriteString(subRow("DRYness %", f2(d)))
		}
		b.WriteString(bd + "\n")
	}
	writeFooter(&b, total, o)
	return b.String()
}

func subRow(label string, val string) string {
	return fmt.Sprintf("%-20s%5s%12s\n", label, "", val)
}

func writeLangRow(b *strings.Builder, r *LangRow, o *Options) {
	if o.Wide {
		cl := 0.0
		if r.Lines > 0 {
			cl = float64(r.Complexity) / float64(r.Lines)
		}
		b.WriteString(fmt.Sprintf("%-38s%5s%10s%9s%10s%9s%11s%17s\n", r.Name, comma(r.Count), comma(r.Lines), comma(r.Blank), comma(r.Comment), comma(r.Code), comma(r.Complexity), f2(cl)))
	} else {
		b.WriteString(fmt.Sprintf("%-20s%5s%12s%10s%10s%11s%11s\n", r.Name, comma(r.Count), comma(r.Lines), comma(r.Blank), comma(r.Comment), comma(r.Code), comma(r.Complexity)))
	}
	if o.Percent {
		t := totalOf(rows, o)
		if o.Wide {
			b.WriteString(fmt.Sprintf("%-20s%5s%12s%10s%10s%11s%11s\n", "Percentage", pct(r.Count, t.Files), pct(r.Lines, t.Lines), pct(r.Blank, t.Blank), pct(r.Comment, t.Comment), pct(r.Code, t.Code), pct(r.Complexity, t.Complexity)))
		} else {
			b.WriteString(fmt.Sprintf("%-20s%5s%12s%10s%10s%11s%11s\n", "Percentage", pct(r.Count, t.Files), pct(r.Lines, t.Lines), pct(r.Blank, t.Blank), pct(r.Comment, t.Comment), pct(r.Code, t.Code), pct(r.Complexity, t.Complexity)))
		}
	}
	if o.Character && r.LineLength != nil {
		b.WriteString(subRow("MaxLine / MeanLine", fmt.Sprintf("%s%s%s", comma(r.LineLength.Max), "", ""))[:0])
		b.WriteString(fmt.Sprintf("%-20s%5s%12s\n", "MaxLine / MeanLine", comma(r.LineLength.Max), f0or2(r.LineLength.Average)))
	}
	if o.Uloc || o.Dryness {
		b.WriteString(subRow("(ULOC)", comma(r.ULOC)))
	}
	if !o.NoHborder {
		if o.Ci {
			b.WriteString(borderASCII + "\n")
		} else {
			b.WriteString(borderASCII + "\n")
		}
	}
}

func f0or2(v float64) string { return trimFloat(v, 0) }

func totalOf(rows []*LangRow, o *Options) *LangRow {
	t := &LangRow{Name: "Total"}
	for _, r := range rows {
		t.Count += r.Count
		t.Lines += r.Lines
		t.Blank += r.Blank
		t.Comment += r.Comment
		t.Code += r.Code
		t.Complexity += r.Complexity
	}
	return t
}

func writeFooter(b *strings.Builder, total *LangRow, o *Options) {
	bd := border(o.Ci)
	if !o.NoCocomo {
		eff, months, people, cost := Cocomo(total.Code, o)
		name := cocomoName(o.CocomoProjectType)
		if o.SloccountFormat {
			b.WriteString(fmt.Sprintf("Total Physical Source Lines of Code (SLOC)                     = %s\n", comma(total.Code)))
			b.WriteString(fmt.Sprintf("Development Effort Estimate, Person-Years (Person-Months)      = %.2f (%.2f)\n", eff/12, eff))
			b.WriteString(fmt.Sprintf(" (Basic COCOMO model, Person-Months = %.2f*(KSLOC**%s)*%s)\n", cocomoA(o.CocomoProjectType), cocomoBstr(o.CocomoProjectType), eafStr(o.Eaf)))
			b.WriteString(fmt.Sprintf("Schedule Estimate, Years (Months)                              = %.2f (%.2f)\n", months/12, months))
			b.WriteString(" (Basic COCOMO model, Months = 2.50*(person-months**0.38))\n")
			b.WriteString(fmt.Sprintf("Estimated Average Number of Developers (Effort/Schedule)       = %.2f\n", people))
			b.WriteString(fmt.Sprintf("Total Estimated Cost to Develop                                = %s%s\n", o.CurrencySymbol, comma(int(cost))))
			b.WriteString(fmt.Sprintf(" (average salary = %s%s/year, overhead = %.2f)\n", o.CurrencySymbol, comma(o.AvgWage), o.Overhead))
			b.WriteString(bd + "\n")
			return
		}
		b.WriteString(fmt.Sprintf("Estimated Cost to Develop (%s) %s%s\n", name, o.CurrencySymbol, comma(int(cost))))
		b.WriteString(fmt.Sprintf("Estimated Schedule Effort (%s) %.2f months\n", name, months))
		b.WriteString(fmt.Sprintf("Estimated People Required (%s) %.2f\n", name, people))
		b.WriteString(bd + "\n")
	}
	if o.Locomo || o.CostComparison {
		writeLocomo(b, total, o)
		b.WriteString(bd + "\n")
	}
	if !o.NoSize {
		mb := float64(total.Bytes) / 1000000.0
		b.WriteString(fmt.Sprintf("Processed %s bytes, %s megabytes (%s)\n", comma(int(total.Bytes)), f3(mb), sizeUnitName(o.SizeUnit, total.Bytes)))
		b.WriteString(bd + "\n")
	}
}

func eafStr(e float64) string {
	s := trimFloat(e, 2)
	return s
}

func sizeUnitName(unit string, bytes int64) string {
	switch unit {
	case "binary":
		return "binary"
	case "mixed":
		return "mixed"
	}
	return "SI"
}
GOEOF
echo ok"}

