package main

import (
	"math"
	"strconv"
	"strings"
)

type cocomoCoeff struct {
	A, B, M, P float64
}

func cocomoCoeffs(projectType string) cocomoCoeff {
	switch strings.ToLower(projectType) {
	case "organic":
		return cocomoCoeff{2.4, 1.05, 2.5, 0.38}
	case "semi-detached":
		return cocomoCoeff{3.0, 1.12, 2.5, 0.35}
	case "embedded":
		return cocomoCoeff{3.6, 1.20, 2.5, 0.32}
	}
	if strings.HasPrefix(strings.ToLower(projectType), "custom,") {
		parts := strings.Split(projectType, ",")
		if len(parts) == 5 {
			a, _ := strconv.ParseFloat(parts[1], 64)
			b, _ := strconv.ParseFloat(parts[2], 64)
			m, _ := strconv.ParseFloat(parts[3], 64)
			p, _ := strconv.ParseFloat(parts[4], 64)
			return cocomoCoeff{a, b, m, p}
		}
	}
	return cocomoCoeff{2.4, 1.05, 2.5, 0.38}
}

func cocomoA(t string) float64  { return cocomoCoeffs(t).A }
func cocomoB(t string) float64  { return cocomoCoeffs(t).B }
func cocomoM(t string) float64  { return cocomoCoeffs(t).M }
func cocomoP(t string) float64  { return cocomoCoeffs(t).P }

func cocomoBstr(t string) string { return trimFloat(cocomoB(t), 2) }

func cocomoName(t string) string {
	l := strings.ToLower(t)
	switch l {
	case "organic", "semi-detached", "embedded":
		return l
	}
	if strings.HasPrefix(l, "custom,") {
		return "custom"
	}
	return "organic"
}

// Cocomo computes the basic COCOMO estimate.
func Cocomo(code int, o *Options) (effort, months, people, cost float64) {
	c := cocomoCoeffs(o.CocomoProjectType)
	ksloc := float64(code) / 1000.0
	effort = c.A * math.Pow(ksloc, c.B) * o.Eaf
	months = c.M * math.Pow(effort, c.P)
	if months != 0 {
		people = effort / months
	}
	monthly := o.AvgWage / 12
	cost = effort * float64(monthly) * o.Overhead
	return effort, months, people, cost
}

// EstimatedCost returns the cost for the json2 format.
func EstimatedCost(code int, o *Options) float64 {
	_, _, _, cost := Cocomo(code, o)
	return cost
}

// EstimatedSchedule returns the schedule months for the json2 format.
func EstimatedSchedule(code int, o *Options) float64 {
	_, months, _, _ := Cocomo(code, o)
	return months
}

// EstimatedPeople returns the people estimate for the json2 format.
func EstimatedPeople(code int, o *Options) float64 {
	_, _, people, _ := Cocomo(code, o)
	return people
}
