{"command": "cd /workspace && cat > src/formats2.go <<'GOEOF'
package main

import (
	"fmt"
	"sort"
	"strings"
)

func jsonRow(name string, bytes int64, codeBytes int64, lines, code, comment, blank, complexity int, count int, weighted float64, files []string, lineLength *LineLength, uloc int, byFile bool, fstats []*FileStat) string {
	var b strings.Builder
	b.WriteString("{")
	b.WriteString(fmt.Sprintf("\"Name\":%s,", jStr(name)))
	b.WriteString(fmt.Sprintf("\"Bytes\":%d,", bytes))
	b.WriteString(fmt.Sprintf("\"CodeBytes\":%d,", codeBytes))
	b.WriteString(fmt.Sprintf("\"Lines\":%d,", lines))
	b.WriteString(fmt.Sprintf("\"Code\":%d,", code))
	b.WriteString(fmt.Sprintf("\"Comment\":%d,", comment))
	b.WriteString(fmt.Sprintf("\"Blank\":%d,", blank))
	b.WriteString(fmt.Sprintf("\"Complexity\":%d,", complexity))
	b.WriteString(fmt.Sprintf("\"Count\":%d,", count))
	b.WriteString(fmt.Sprintf("\"WeightedComplexity\":%s,", jFloat(weighted)))
	if byFile {
		b.WriteString("\"Files\":[")
		for i, f := range fstats {
			if i > 0 {
				b.WriteString(",")
			}
			b.WriteString(jsonFile(f))
		}
		b.WriteString("],")
	} else {
		b.WriteString("\"Files\":[],")
	}
	if lineLength != nil {
		b.WriteString(fmt.Sprintf("\"LineLength\":{\"Files\":%d,\"Lines\":%d,\"MaxLineLength\":%d,\"AverageLineLength\":%s},", lineLength.Files, lineLength.Lines, lineLength.Max, jFloat(lineLength.Average)))
	} else {
		b.WriteString("\"LineLength\":null,")
	}
	b.WriteString(fmt.Sprintf("\"ULOC\":%d}", uloc))
	return b.String()
}

func jsonFile(f *FileStat) string {
	var b strings.Builder
	b.WriteString("{")
	b.WriteString(fmt.Sprintf("\"Language\":%s,", jStr(f.Language)))
	b.WriteString("\"PossibleLanguages\":[")
	for i, p := range f.PossibleLanguages {
		if i > 0 {
			b.WriteString(",")
		}
		b.WriteString(jStr(p))
	}
	b.WriteString("],")
	b.WriteString(fmt.Sprintf("\"Filename\":%s,", jStr(f.Filename)))
	b.WriteString(fmt.Sprintf("\"Extension\":%s,", jStr(f.Extension)))
	b.WriteString(fmt.Sprintf("\"Location\":%s,", jStr(f.Location)))
	b.WriteString(fmt.Sprintf("\"Symlocation\":%s,", jStr(f.Symlocation)))
	b.WriteString(fmt.Sprintf("\"Bytes\":%d,", f.Bytes))
	b.WriteString(fmt.Sprintf("\"Lines\":%d,", f.Lines))
	b.WriteString(fmt.Sprintf("\"Code\":%d,", f.Code))
	b.WriteString(fmt.Sprintf("\"Comment\":%d,", f.Comment))
	b.WriteString(fmt.Sprintf("\"Blank\":%d,", f.Blank))
	b.WriteString(fmt.Sprintf("\"Complexity\":%d,", f.Complexity))
	b.WriteString(fmt.Sprintf("\"WeightedComplexity\":%s,", jFloat(0)))
	b.WriteString("\"Hash\":null,")
	b.WriteString(fmt.Sprintf("\"Binary\":%t,", f.Binary))
	b.WriteString(fmt.Sprintf("\"Minified\":%t,", f.Minified))
	b.WriteString(fmt.Sprintf("\"Generated\":%t,", f.Generated))
	b.WriteString(fmt.Sprintf("\"EndPoint\":%d,", f.EndPoint))
	b.WriteString(fmt.Sprintf("\"Uloc\":%d}", f.Uloc))
	return b.String()
}

func jStr(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for _, r := range s {
		switch r {
		case '"':
			b.WriteString("\\\"")
		case '\\':
			b.WriteString("\\\\")
		case '\n':
			b.WriteString("\\n")
		case '\r':
			b.WriteString("\\r")
		case '\t':
			b.WriteString("\\t")
		default:
			if r < 0x20 {
				b.WriteString(fmt.Sprintf("\\u%04x", r))
			} else {
				b.WriteRune(r)
			}
		}
	}
	b.WriteByte('"')
	return b.String()
}

func jFloat(v float64) string {
	s := strconv.FormatFloat(v, 'g', -1, 64)
	return s
}

// JSONFormat renders the json output format.
func JSONFormat(rows []*LangRow, total *LangRow, o *Options) string {
	var parts []string
	for _, r := range rows {
		parts = append(parts, jsonRow(r.Name, r.Bytes, 0, r.Lines, r.Code, r.Comment, r.Blank, r.Complexity, r.Count, r.WeightedComplexity, nil, r.LineLength, r.ULOC, o.ByFile, r.Files))
	}
	return "[" + strings.Join(parts, ",") + "]"
}

// JSON2Format renders the json2 output format.
func JSON2Format(rows []*LangRow, total *LangRow, o *Options) string {
	var parts []string
	for _, r := range rows {
		parts = append(parts, jsonRow(r.Name, r.Bytes, 0, r.Lines, r.Code, r.Comment, r.Blank, r.Complexity, r.Count, r.WeightedComplexity, nil, r.LineLength, r.ULOC, o.ByFile, r.Files))
	}
	cost, months, people, _ := Cocomo(total.Code, o)
	return "{\"languageSummary\":[" + strings.Join(parts, ",") + "],\"estimatedCost\":" + jFloat(cost) +
		",\"estimatedScheduleMonths\":" + jFloat(months) + ",\"estimatedPeople\":" + jFloat(people) + "}"
}

// CSVFormat renders the csv output format.
func CSVFormat(rows []*LangRow, total *LangRow, o *Options) string {
	var b strings.Builder
	if o.ByFile {
		b.WriteString("Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,ULOC\n")
		var all []*FileStat
		for _, r := range rows {
			all = append(all, r.Files...)
		}
		SortFilesByFilename(all, o.Sort)
		for _, f := range all {
			b.WriteString(csvLine([]string{f.Language, f.Location, f.Filename, itoa(f.Lines), itoa(f.Code), itoa(f.Comment), itoa(f.Blank), itoa(f.Complexity), itoa64(f.Bytes), itoa(f.Uloc)}))
			b.WriteString("\n")
		}
		return b.String()
	}
	b.WriteString("Language,Lines,Code,Comments,Blanks,Complexity,Bytes,Files,ULOC\n")
	for _, r := range rows {
		b.WriteString(csvLine([]string{r.Name, itoa(r.Lines), itoa(r.Code), itoa(r.Comment), itoa(r.Blank), itoa(r.Complexity), itoa64(r.Bytes), itoa(r.Count), itoa(r.ULOC)}))
		b.WriteString("\n")
	}
	return b.String()
}

// SortFilesByFilename sorts file stats by filename unless a specific sort is requested.
func SortFilesByFilename(files []*FileStat, sortKey string) {
	if sortKey == "" || sortKey == "files" {
		sort.SliceStable(files, func(i, j int) bool { return files[i].Filename < files[j].Filename })
		return
	}
	SortFiles(files, sortKey)
}

func itoa(i int) string    { return fmt.Sprintf("%d", i) }
func itoa64(i int64) string { return fmt.Sprintf("%d", i) }

func csvField(s string) string {
	need := false
	for _, c := range s {
		if c == ',' || c == '"' || c == '\n' || c == '\r' {
			need = true
		}
	}
	if !need {
		return s
	}
	return "\"" + strings.ReplaceAll(s, "\"", "\"\"") + "\""
}

func csvLine(fields []string) string {
	var out []string
	for _, f := range fields {
		out = append(out, csvField(f))
	}
	return strings.Join(out, ",")
}

// CSVStreamFormat renders the csv-stream output format.
func CSVStreamFormat(rows []*LangRow, total *LangRow, o *Options) string {
	var b strings.Builder
	b.WriteString("Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc\n")
	for _, r := range rows {
		for _, f := range r.Files {
			b.WriteString(csvLine([]string{r.Name, "\"" + f.Location + "\"", "\"" + f.Filename + "\"", itoa(f.Lines), itoa(f.Code), itoa(f.Comment), itoa(f.Blank), itoa(f.Complexity), itoa64(f.Bytes), itoa(f.Uloc)}))
			b.WriteString("\n")
		}
	}
	return b.String()
}

// OpenMetricsFormat renders the openmetrics output format.
func OpenMetricsFormat(rows []*LangRow, o *Options) string {
	var b strings.Builder
	b.WriteString("# TYPE scc_files gauge\n# HELP scc_files Number of sourcecode files.\n")
	b.WriteString("# TYPE scc_lines gauge\n# HELP scc_lines Number of lines.\n")
	b.WriteString("# TYPE scc_code gauge\n# HELP scc_code Number of lines of actual code.\n")
	b.WriteString("# TYPE scc_comments gauge\n# HELP scc_comments Number of comments.\n")
	b.WriteString("# TYPE scc_blanks gauge\n# HELP scc_blanks Number of blank lines.\n")
	b.WriteString("# TYPE scc_complexity gauge\n# HELP scc_complexity Code complexity.\n")
	b.WriteString("# TYPE scc_bytes gauge\n# UNIT scc_bytes bytes\n# HELP scc_bytes Size in bytes.\n")
	for _, r := range rows {
		b.WriteString(fmt.Sprintf("scc_files{language=%s} %d\n", jStr(r.Name), r.Count))
		b.WriteString(fmt.Sprintf("scc_lines{language=%s} %d\n", jStr(r.Name), r.Lines))
		b.WriteString(fmt.Sprintf("scc_code{language=%s} %d\n", jStr(r.Name), r.Code))
		b.WriteString(fmt.Sprintf("scc_comments{language=%s} %d\n", jStr(r.Name), r.Comment))
		b.WriteString(fmt.Sprintf("scc_blanks{language=%s} %d\n", jStr(r.Name), r.Blank))
