func jsonFile(f *FileStat) string {
	var b strings.Builder
	b.WriteString("{")
	b.WriteString(fmt.Sprintf("\"Language\":%s,", jStr(f.Language)))
	b.WriteString("\"PossibleLanguages\":[")
	for i, p := range f.PossibleLanguages {
		if i > 0 {
			b.WriteString(",")
		}
		b.WriteString(jStr(p))
	}
	b.WriteString("],")
	b.WriteString(fmt.Sprintf("\"Filename\":%s,", jStr(f.Filename)))
	b.WriteString(fmt.Sprintf("\"Extension\":%s,", jStr(f.Extension)))
	b.WriteString(fmt.Sprintf("\"Location\":%s,", jStr(f.Location)))
	b.WriteString(fmt.Sprintf("\"Symlocation\":%s,", jStr(f.Symlocation)))
	b.WriteString(fmt.Sprintf("\"Bytes\":%d,", f.Bytes))
	b.WriteString(fmt.Sprintf("\"Lines\":%d,", f.Lines))
	b.WriteString(fmt.Sprintf("\"Code\":%d,", f.Code))
	b.WriteString(fmt.Sprintf("\"Comment\":%d,", f.Comment))
	b.WriteString(fmt.Sprintf("\"Blank\":%d,", f.Blank))
	b.WriteString(fmt.Sprintf("\"Complexity\":%d,", f.Complexity))
	b.WriteString(fmt.Sprintf("\"WeightedComplexity\":%s,", jFloat(0)))
	b.WriteString("\"Hash\":null,")
	b.WriteString(fmt.Sprintf("\"Binary\":%t,", f.Binary))
	b.WriteString(fmt.Sprintf("\"Minified\":%t,", f.Minified))
	b.WriteString(fmt.Sprintf("\"Generated\":%t,", f.Generated))
	b.WriteString(fmt.Sprintf("\"EndPoint\":%d,", f.EndPoint))
	b.WriteString(fmt.Sprintf("\"Uloc\":%d}", f.Uloc))
	return b.String()
}

func jStr(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for _, r := range s {
		switch r {
		case '"':
			b.WriteString("\\\"")
		case '\\':
			b.WriteString("\\\\")
		case '\n':
			b.WriteString("\\n")
		case '\r':
			b.WriteString("\\r")
		case '\t':
			b.WriteString("\\t")
		default:
			if r < 0x20 {
				b.WriteString(fmt.Sprintf("\\u%04x", r))
			} else {
				b.WriteRune(r)
			}
		}
	}
	b.WriteByte('"')
	return b.String()
}

func jFloat(v float64) string {
	s := strconv.FormatFloat(v, 'g', -1, 64)
	return s
}

