// ClocYamlFormat renders the cloc-yaml output format.
func ClocYamlFormat(rows []*LangRow, total *LangRow, elapsed float64, o *Options) string {
	var b strings.Builder
	b.WriteString("# https://github.com/boyter/scc/\n")
	b.WriteString("header:\n")
	b.WriteString("  url: https://github.com/boyter/scc/\n")
	b.WriteString("  version: 3.7.0\n")
	b.WriteString(fmt.Sprintf("  elapsed_seconds: %s\n", trimFloat(elapsed, 3)))
	b.WriteString(fmt.Sprintf("  n_files: %d\n", total.Count))
	b.WriteString(fmt.Sprintf("  n_lines: %d\n", total.Lines))
	fps := 0.0
	lps := 0.0
	if elapsed > 0 {
		fps = float64(total.Count) / elapsed
		lps = float64(total.Lines) / elapsed
	}
	b.WriteString(fmt.Sprintf("  files_per_second: %s\n", formatYamlFloat(fps)))
	b.WriteString(fmt.Sprintf("  lines_per_second: %s\n", formatYamlFloat(lps)))
	for _, r := range rows {
		b.WriteString(fmt.Sprintf("%s:\n", r.Name))
		b.WriteString(fmt.Sprintf("  name: %s\n", r.Name))
		b.WriteString(fmt.Sprintf("  code: %d\n", r.Code))
		b.WriteString(fmt.Sprintf("  comment: %d\n", r.Comment))
		b.WriteString(fmt.Sprintf("  blank: %d\n", r.Blank))
		b.WriteString(fmt.Sprintf("  nFiles: %d\n", r.Count))
	}
	b.WriteString("SUM:\n")
	b.WriteString(fmt.Sprintf("  code: %d\n", total.Code))
	b.WriteString(fmt.Sprintf("  comment: %d\n", total.Comment))
	b.WriteString(fmt.Sprintf("  blank: %d\n", total.Blank))
	b.WriteString(fmt.Sprintf("  nFiles: %d\n", total.Count))
	return b.String()
}

func formatYamlFloat(v float64) string {
	if v == float64(int64(v)) {
		return fmt.Sprintf("%d", int64(v))
	}
	return trimFloat(v, 6)
}

// HTMLFormat renders the html and html-table output formats.
func HTMLFormat(rows []*LangRow, total *LangRow, o *Options) string {
	var b strings.Builder
	if !o.TableOnly() {
		b.WriteString("<html lang=\"en\"><head><meta charset=\"utf-8\" /><title>scc html output</title><style>table { border-collapse: collapse; }td, th { border: 1px solid #999; padding: 0.5rem; text-align: left;}</style></head><body>")
	}
	b.WriteString("<table id=\"scc-table\">\n\t<thead><tr>\n")
	b.WriteString("\t\t<th>Language</th>\n\t\t<th>Files</th>\n\t\t<th>Lines</th>\n\t\t<th>Blank</th>\n\t\t<th>Comment</th>\n\t\t<th>Code</th>\n\t\t<th>Complexity</th>\n\t\t<th>Bytes</th>\n\t\t<th>Uloc</th>\n")
	b.WriteString("\t</tr></thead>\n\t<tbody>")
	for _, r := range rows {
		b.WriteString(fmt.Sprintf("<tr>\n\t\t<th>%s</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t</tr>", r.Name, r.Count, r.Lines, r.Blank, r.Comment, r.Code, r.Complexity, r.Bytes, r.ULOC))
	}
	b.WriteString("</tbody>\n\t<tfoot><tr>\n")
	b.WriteString(fmt.Sprintf("\t\t<th>Total</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t</tr></tfoot></table>", total.Count, total.Lines, total.Blank, total.Comment, total.Code, total.Complexity, total.Bytes, total.ULOC))
	if !o.TableOnly() {
		b.WriteString("</body></html>\n")
	}
	return b.String()
}

func (o *Options) TableOnly() bool { return o.Format == "html-table" }

// SQLFormat renders the sql output formats.
func SQLFormat(rows []*LangRow, total *LangRow, o *Options, project string, elapsed float64) string {
	var b strings.Builder
	if o.Format == "sql" {
		b.WriteString("create table metadata (   -- github.com/boyter/scc v 3.7.0\n")
		b.WriteString("             timestamp text,\n")
		b.WriteString("             Project   text,\n")
		b.WriteString("             elapsed_s real,\n")
		b.WriteString("             estimated_cost real,\n")
		b.WriteString("             estimated_schedule_months real,\n")
		b.WriteString("             estimated_people real);\n")
		b.WriteString("create table t        (\n")
		b.WriteString("             Project       text   ,\n")
		b.WriteString("             Language      text   ,\n")
		b.WriteString("             File          text   ,\n")
		b.WriteString("             File_dirname  text   ,\n")
		b.WriteString("             File_basename text   ,\n")
		b.WriteString("             nByte         integer,\n")
		b.WriteString("             nBlank        integer,\n")
		b.WriteString("             nComment      integer,\n")
		b.WriteString("             nCode         integer,\n")
		b.WriteString("             nComplexity   integer,\n")
		b.WriteString("             nUloc         integer    \n")
		b.WriteString(");\n")
	}
	b.WriteString("\nbegin transaction;\n")
	var all []*FileStat
	for _, r := range rows {
		all = append(all, r.Files...)
	}
	SortFilesByFilename(all, o.Sort)
	for _, f := range all {
		dir := ""
		base := f.Filename
		if i := strings.LastIndexByte(f.Location, '/'); i >= 0 {
			dir = f.Location[:i]
			base = f.Location[i+1:]
		}
		b.WriteString(fmt.Sprintf("insert into t values(%s, %s, %s, %s, %s, %d, %d, %d, %d, %d, %d);\n",
			sqlStr(project), sqlStr(f.Language), sqlStr(f.Location), sqlStr(dir), sqlStr(base),
			f.Bytes, f.Blank, f.Comment, f.Code, f.Complexity, f.Uloc))
	}
	b.WriteString("commit;\n")
	cost, months, people, _ := Cocomo(total.Code, o)
	b.WriteString("begin transaction;\n")
	b.WriteString(fmt.Sprintf("insert into metadata values('%s', %s, %.6f, %.6f, %.6f, %.6f);\n", timestamp(), sqlStr(project), elapsed, cost, months, people))
	b.WriteString("commit;")
	return b.String()
}

func sqlStr(s string) string {
	return "'" + strings.ReplaceAll(s, "'", "''") + "'"
}

var startTime = nowTime()

func timestamp() string {
	return nowTime().Format("2006-01-02 15:04:05")
}
