package main

import (
	"fmt"
	"os"
	"regexp"
	"strings"
	"time"
)

const version = "3.7.0"

func nowTime() time.Time { return time.Now() }

func main() {
	start := time.Now()
	help, ver := HandleHelpVersion(os.Args[1:])
	if ver {
		PrintVersion()
		return
	}
	if help {
		PrintHelp()
		return
	}
	o, _, err := ParseFlags(os.Args[1:])
	if err != nil {
		ExitWithError(err)
		return
	}
	if o.Wide {
		o.NoComplexity = false
	}
	if o.Dryness {
		o.Uloc = true
	}
	if o.NoMinGen {
		o.MinGen = true
	}
	if o.NoMin {
		o.Min = true
	}
	if o.NoGen {
		o.Gen = true
	}
	if o.Languages {
		printLanguages()
		return
	}
	c := &Collector{Opts: o}
	for _, m := range o.NotMatch {
		re, err := regexp.Compile(m)
		if err == nil {
			c.notMatch = append(c.notMatch, re)
		}
	}
	// ignore files
	if !o.NoGitignore || !o.NoIgnore || !o.NoSccIgnore {
		loadIgnoreFiles(c, ".")
	}
	if len(o.Args) == 0 {
		c.walk(".")
	} else {
		for _, a := range o.Args {
			c.walk(a)
		}
	}
	rows, total := Aggregate(c.Files, o)
	elapsed := time.Since(start).Seconds()
	out := render(rows, total, c.Files, o, elapsed)
	if o.Output != "" {
		f, err := os.Create(o.Output)
		if err == nil {
			f.WriteString(out)
			f.Close()
			return
		}
	}
	fmt.Print(out)
}

func render(rows []*LangRow, total *LangRow, files []*FileStat, o *Options, elapsed float64) string {
	switch o.Format {
	case "json":
		return JSONFormat(rows, total, o)
	case "json2":
		return JSON2Format(rows, total, o)
	case "csv":
		return CSVFormat(rows, total, o)
	case "csv-stream":
		return CSVStreamFormat(rows, total, o)
	case "cloc-yaml":
		return ClocYamlFormat(rows, total, elapsed, o)
	case "html", "html-table":
		return HTMLFormat(rows, total, o)
	case "sql", "sql-insert":
		return SQLFormat(rows, total, o, sqlProjectName(o), elapsed)
	case "openmetrics":
		return OpenMetricsFormat(rows, o)
	default:
		return Tabular(rows, total, files, o)
	}
}

func sqlProjectName(o *Options) string {
	if o.SqlProject != "" {
		return o.SqlProject
	}
	return "."
}

func printLanguages() {
	names := make([]string, 0, len(Langs))
	for i := range Langs {
		names = append(names, Langs[i].Name)
	}
	sortStrings(names)
	for _, n := range names {
		var exts []string
		for i := range Langs {
			if Langs[i].Name == n {
				exts = Langs[i].Exts
			}
		}
		fmt.Printf("%s (%s)\n", n, strings.Join(exts, ","))
	}
}

func sortStrings(s []string) {
	for i := 1; i < len(s); i++ {
		for j := i; j > 0 && s[j] < s[j-1]; j-- {
			s[j], s[j-1] = s[j-1], s[j]
		}
	}
}

func loadIgnoreFiles(c *Collector, dir string) {
	for _, name := range []string{".gitignore", ".ignore", ".sccignore"} {
		if name == ".gitignore" && c.Opts.NoGitignore {
			continue
		}
		if name == ".ignore" && c.Opts.NoIgnore {
			continue
		}
		if name == ".sccignore" && c.Opts.NoSccIgnore {
			continue
		}
		full := dir + "/" + name
		if _, err := os.Stat(full); err == nil {
			c.ignoreRules = append(c.ignoreRules, parseIgnoreFile(full, dir)...)
		}
	}
}
