func rowVals(r *LangRow, o *Options) []string {
	if o.Wide {
		cl := 0.0
		if r.Lines > 0 {
			cl = float64(r.Complexity) / float64(r.Lines)
		}
		return []string{comma(r.Count), comma(r.Lines), comma(r.Blank), comma(r.Comment), comma(r.Code), comma(r.Complexity), f2(cl)}
	}
	if o.NoComplexity {
		return []string{comma(r.Count), comma(r.Lines), comma(r.Blank), comma(r.Comment), comma(r.Code)}
	}
	return []string{comma(r.Count), comma(r.Lines), comma(r.Blank), comma(r.Comment), comma(r.Code), comma(r.Complexity)}
}

func langRowStr(r *LangRow, o *Options) string {
	return buildCols(r.Name, rowVals(r, o), endsFor(o), rowNameWidth(o))
}

func langRowVals(name string, r *LangRow, o *Options) string {
	return buildCols(name, rowVals(r, o), endsFor(o), rowNameWidth(o))
}

func fileRowStr(f *FileStat, o *Options) string {
	ends := endsFor(o)
	var vals []string
	if o.Wide {
		cl := 0.0
		if f.Lines > 0 {
			cl = float64(f.Complexity) / float64(f.Lines)
		}
		vals = []string{"", comma(f.Lines), comma(f.Blank), comma(f.Comment), comma(f.Code), comma(f.Complexity), f2(cl)}
	} else if o.NoComplexity {
		vals = []string{"", comma(f.Lines), comma(f.Blank), comma(f.Comment), comma(f.Code)}
	} else {
		vals = []string{"", comma(f.Lines), comma(f.Blank), comma(f.Comment), comma(f.Code), comma(f.Complexity)}
	}
	return buildCols(f.Location, vals, ends, rowNameWidth(o))
}

func pctRowStr(r *LangRow, tot *LangRow, o *Options) string {
	ends := endsFor(o)
	var vals []string
	if o.Wide {
		vals = []string{pct(r.Count, tot.Count), pct(r.Lines, tot.Lines), pct(r.Blank, tot.Blank), pct(r.Comment, tot.Comment), pct(r.Code, tot.Code), pct(r.Complexity, tot.Complexity), ""}
