new='''// HTMLFormat renders the html and html-table output formats.
func HTMLFormat(rows []*LangRow, total *LangRow, o *Options) string {
	var b strings.Builder
	if !o.TableOnly() {
		b.WriteString("<html lang=\\"en\\"><head><meta charset=\\"utf-8\\" /><title>scc html output</title><style>table { border-collapse: collapse; }td, th { border: 1px solid #999; padding: 0.5rem; text-align: left;}</style></head><body>")
	}
	b.WriteString("<table id=\\"scc-table\\">\\n\\t<thead><tr>\\n\\t\\t<th>Language</th>\\n\\t\\t<th>Files</th>\\n\\t\\t<th>Lines</th>\\n\\t\\t<th>Blank</th>\\n\\t\\t<th>Comment</th>\\n\\t\\t<th>Code</th>\\n\\t\\t<th>Complexity</th>\\n\\t\\t<th>Bytes</th>\\n\\t\\t<th>Uloc</th>\\n\\t</tr></thead>\\n\\t<tbody><tr>\\n")
	for i, r := range rows {
		u := 0
		if o.Uloc {
			u = r.ULOC
		}
		b.WriteString(fmt.Sprintf("\\t\\t<th>%s</th>\\n\\t\\t<th>%d</th>\\n\\t\\t<th>%d</th>\\n\\t\\t<th>%d</th>\\n\\t\\t<th>%d</th>\\n\\t\\t<th>%d</th>\\n\\t\\t<th>%d</th>\\n\\t\\t<th>%d</th>\\n\\t\\t<th>%d</th>\\n", r.Name, r.Count, r.Lines, r.Blank, r.Comment, r.Code, r.Complexity, r.Bytes, u))
		if i == len(rows)-1 {
			b.WriteString("\\t</tr></tbody>\\n\\t<tfoot><tr>\\n")
		} else {
			b.WriteString("\\t</tr><tr>\\n")
		}
	}
	tu := 0
	if o.Uloc {
		tu = total.ULOC
	}
	b.WriteString(fmt.Sprintf("\\t\\t<th>Total</th>\\n\\t\\t<th>%d</th>\\n\\t\\t<th>%d</th>\\n\\t\\t<th>%d</th>\\n\\t\\t<th>%d</th>\\n\\t\\t<th>%d</th>\\n\\t\\t<th>%d</th>\\n\\t\\t<th>%d</th>\\n\\t\\t<th>%d</th>\\n", total.Count, total.Lines, total.Blank, total.Comment, total.Code, total.Complexity, total.Bytes, tu))
	cocomoRow := ""
	if !o.NoCocomo {
		_, months, people, cost := Cocomo(total.Code, o)
		name := cocomoName(o.CocomoProjectType)
		cocomoRow = fmt.Sprintf("\\t<tr>\\n\\t\\t<th colspan=\\"9\\">Estimated Cost to Develop (%s) %s%s<br>Estimated Schedule Effort (%s) %.2f months<br>Estimated People Required (%s) %.2f<br></th>\\n", name, o.CurrencySymbol, comma(int(cost)), name, months, name, people)
	}
	if cocomoRow != "" {
		b.WriteString("\\t</tr>\\n" + cocomoRow + "\\t</tr></tfoot>\\n\\t</table>")
	} else {
		b.WriteString("\\t</tr></tfoot></table>")
	}
	if !o.TableOnly() {
		b.WriteString("</body></html>\\n")
	}
	return b.String()
}

'''
s=s[:start]+new+s[end:]
open('src/formats2.go','w').write(s)
