package main

import (
	"fmt"
	"math"
	"strings"
)

type locomoPreset struct {
	InPrice  float64
	OutPrice float64
	TPS      float64
}

var locomoPresets = map[string]locomoPreset{
	"large":  {10.0, 30.0, 30},
	"medium": {3.0, 15.0, 50},
	"small":  {0.5, 2.0, 100},
	"local":  {0.0, 0.0, 15},
}

func writeLocomo(b *strings.Builder, total *LangRow, o *Options) {
	preset, ok := locomoPresets[o.LocomoPreset]
	if !ok {
		preset = locomoPresets["medium"]
	}
	inPrice, outPrice, tps := preset.InPrice, preset.OutPrice, preset.TPS
	if o.LocomoInputPrice > 0 {
		inPrice = o.LocomoInputPrice
	}
	if o.LocomoOutputPrice > 0 {
		outPrice = o.LocomoOutputPrice
	}
	if o.LocomoTps > 0 {
		tps = o.LocomoTps
	}
	tokensPerLine := 10.0
	inputPerLine := 20.0
	complexityWeight := 1.0
	iterations := 1.5
	iterationWeight := 2.0
	if o.LocomoConfig != "" {
		parts := strings.Split(o.LocomoConfig, ",")
		if len(parts) == 5 {
			var vals [5]float64
			allOk := true
			for i, p := range parts {
				v, err := parseFloat(p)
				if err != nil {
					allOk = false
					break
				}
				vals[i] = v
			}
			if allOk {
				tokensPerLine, inputPerLine, complexityWeight, iterations, iterationWeight = vals[0], vals[1], vals[2], vals[3], vals[4]
			}
		}
	}
	cycles := iterations
	lines := float64(total.Lines)
	if lines > 0 {
		cycles = iterations + iterationWeight*math.Sqrt(float64(total.Complexity)/lines)
	}
	if o.LocomoCycles > 0 {
		cycles = o.LocomoCycles
	}
	inTok := (lines*1.5 + float64(total.Complexity)*5.5) * inputPerLine / 1000000.0
	outTok := float64(total.Code) * tokensPerLine * cycles / 1000000.0
	cost := inTok*inPrice + outTok*outPrice
	minutes := 0.0
	if tps > 0 {
		minutes = outTok * 1000000 / tps / 60
	}
	review := float64(total.Code) * o.LocomoReview / 60
	b.WriteString(fmt.Sprintf("LOCOMO LLM Cost Estimate (%s)\n", o.LocomoPreset))
	b.WriteString(fmt.Sprintf("  Tokens Required (in/out) %.1fM / %.1fM\n", inTok, outTok))
	b.WriteString(fmt.Sprintf("  Cost to Generate %s%.0f\n", o.CurrencySymbol, cost))
	b.WriteString(fmt.Sprintf("  Estimated Cycles %.1f\n", cycles))
	b.WriteString(fmt.Sprintf("  Generation Time (serial) %s\n", formatDuration(minutes)))
	b.WriteString(fmt.Sprintf("  Human Review Time %s\n", formatHours(review*60)))
	b.WriteString("  Disclaimer: rough ballpark for regenerating code using a LLM.\n")
	b.WriteString("  Does not account for context reuse, test generation, or heavy debugging.\n")
}

func formatDuration(minutes float64) string {
	switch {
	case minutes >= 60*24:
		return fmt.Sprintf("%.1f days", minutes/60/24)
	case minutes >= 60:
		return fmt.Sprintf("%.1f hours", minutes/60)
	default:
		return fmt.Sprintf("%.1f minutes", minutes)
	}
}

func formatHours(minutes float64) string {
	if minutes >= 24*60 {
		return fmt.Sprintf("%.1f days", minutes/60/24)
	}
	return fmt.Sprintf("%.1f hours", minutes/60)
}

func parseFloat(s string) (float64, error) {
	var v float64
	var err error
	_, err = fmt.Sscanf(s, "%g", &v)
	return v, err
}
GOEOF
